entries[145061] = { ["name"] = "Nudelwagenbausatz Deluxe", ["text"] = "Wirken in 3 sek.\nReagenzien:\nBlütenfischfilet (5), Zwillingsfischplatte (5), Geschmorte Schildkröte (5), Feuergeisterlachs (5), Pfannengericht nach Vier-Winde-Art (5), Jadehexenbräu (5)\nQuest:\nDas ist eine echte Maßeinheit?\nZone:\nTal der Vier Winde\n\n(5)\nBenutzen: Baut einen Nudelwagen Deluxe auf, um Nudelsuppe Deluxe zu verkaufen!\n\nJede Nudelsuppe Deluxe stellt im Verlauf von 20 Sek. 5288 Gesundheit und 5500 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 15 erhöht.\n35\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen Deluxe zu bauen.\"" }
entries[145062] = { ["name"] = "Nudelwagenbausatz \"Pandarenschatz\"", ["text"] = "Wirken in 3 sek.\nReagenzien:\nRippchen mit schwarzem Pfeffer und Garnelen (5), Chun-Tian-Frühlingsrollen (5), Fischeintopf nach Moguart (5), Gedämpfte Krabbe à la Surprise (5), Küstennebelreisnudeln (5), Wahnsinniges Brauerfrühstück (5)\nQuest:\nDie Geheimzutat ist...\nZone:\nTal der Vier Winde\n\nNudelwagenbausatz \"Pandarenschatz\"\n(5)\nBenutzen: Baut einen Nudelwagen \"Pandarenschatz\" auf, um Nudelsuppe \"Pandarenschatz\" zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 5288 Gesundheit und 5500 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 20 erhöht.\n35\n\"Enthält alles, was Ihr benötigt, um Euren eigenen Nudelwagen 'Pandarenschatz' zu bauen.\"" }
