entries[145411] = { ["name"] = "Wutanfall", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nMacht wütend. Hebt Bewegungseinschränkungs- und Kontrollverlusteffekte auf und macht dagegen immun. Erhöht die Bewegungsgeschwindigkeit um 100%, den verursachten Schaden um 150% und das Angriffstempo um 25%. Hält 10 Sek. lang an." }
