entries[145416] = { ["name"] = "Vergiften", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nFinishing-Move, der sofort Naturschaden proportional zu den auf dem Ziel bestehenden Combopunkten verursacht. Nach Einsatz von 'Vergiften' ist Eure Chance, das Ziel zu vergiften, um 15% erhöht. Dieser Effekt hält eine Sekunde plus jeweils eine weitere Sekunde pro Combopunkt lang an." }
entries[145417] = { ["name"] = "Blutung", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nFinishing-Move, der Schaden im Lauf der Zeit verursacht. Hält pro Combopunkt länger an und verursacht mehr Schaden." }
entries[145418] = { ["name"] = "Zerhäckseln", ["text"] = "25 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der alle Combopunkte eines nahen Ziels verbraucht, um Euer Nahkampfangriffstempo um 40% zu erhöhen. Hält pro Combopunkt länger an." }
entries[145419] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nWenn Eure Waffen vergiftet sind, besteht eine Chance, dass Ihr Zielen, die bereits mit Eurem tödlichen Gift vergiftet sind, 200 Naturschaden zufügt." }
entries[145420] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden." }
entries[145421] = { ["name"] = "Tödliches Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 12 Sek. lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. 1600 Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort 200 Naturschaden.\n(Procchance: 30%)" }
entries[145422] = { ["name"] = "Dolchfächer", ["text"] = "35 Energie\nSofort\nWirbelt sofort herum und schleudert allen Zielen im Umkreis von 10 Metern einen Klingenregen entgegen, der 1005 körperlichen Schaden verursacht. Dieser Angriff hat eine Chance, Eure Ziele zu einer normalen Rate zu vergiften. Gewährt 1005 Combopunkte, wenn Ihr ein Ziel trefft, auf dem bereits Eure Combopunkte aktiv sind." }
entries[145423] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 6 sek. Abklingzeit\nVerbirgt Euch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. Hält an, bis die Aktion abgebrochen wird." }
entries[145424] = { ["name"] = "Fieser Trick", ["text"] = "40 Energie 10 Meter Reichweite\nSofort\nBenötigt Verstohlenheit\nBetäubt das Ziel 4 Sek. lang. Muss im Verstohlenheitsmodus sein. Gewährt 2 Combopunkte." }
entries[145425] = { ["name"] = "Schattenschritt", ["text"] = "100 Meter Reichweite\nSofort\nLässt Euch in die Schatten tauchen, um hinter Eurem Ziel zu erscheinen und 2 Sek. lang eine um 70% erhöhte Bewegungsgeschwindigkeit zu erhalten. [ Täuschung : Wenn Ihr ' Schattenschritt ' bereits erlernt habt, erhaltet Ihr stattdessen 1 zusätzliche Aufladung ' Schattenschritt ' ]" }
entries[145426] = { ["name"] = "Schattenschritt", ["text"] = "25 Meter Reichweite\nSofort 24 sek. Abklingzeit\nLässt Euch in die Schatten tauchen, um hinter dem Gegner zu erscheinen. Danach wird Eure Bewegungsgeschwindigkeit 2 Sek. lang um 70% erhöht." }
entries[145427] = { ["name"] = "Tritt", ["text"] = "Nahkampfreichweite\nSofort 15 sek. Abklingzeit\nEin schneller Tritt, der das Wirken von Zaubern unterbricht und 2 Sek. lang verhindert, dass diese Art Zauber gewirkt werden kann." }
