entries[145434] = { ["name"] = "Arkanschlag", ["text"] = "8% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nÜberzieht einen Gegner mit Energie und verursacht so (66.519% der Zaubermacht) Arkanschaden. Erzeugt eine Arkane Aufladung.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkanschlag' um 60 % und seine Manakosten um 90 % erhöht." }
entries[145435] = { ["name"] = "Arkane Geschosse", ["text"] = "60 Meter Reichweite\nKanalisiert\nKann nur eingesetzt werden, wenn Ihr über 'Freizaubern' verfügt.\n\nFeuert im Verlauf von 2.5 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die insgesamt [5 * (52.6% der Zaubermacht)] Arkanschaden verursachen." }
entries[145436] = { ["name"] = "Arkane Geschosse", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\nFeuert im Verlauf von 2.5 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die pro Welle (52.6% der Zaubermacht) Arkanschaden verursachen. Erzeugt eine Arkane Aufladung.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkane Geschosse' um 60 % erhöht." }
entries[145437] = { ["name"] = "Arkanbeschuss", ["text"] = "4% von Grundmana 40 Meter Reichweite\nSofort 3 sek. Abklingzeit\nSchleudert mehrere Geschosse aus Arkanenergie auf das gegnerische Ziel, die 1006 Arkanschaden verursachen. Der Zauber trifft auch 4 zusätzliche Gegner in der Nähe und fügt ihnen 40% Schaden zu. Verbraucht alle Arkanen Aufladungen.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkanbeschuss' um 60 % erhöht." }
