entries[145532] = { ["name"] = "Frostnova", ["text"] = "Sofort\nFügt Gegnern im Umkreis von 12 Metern vom Zaubernden 100 Frostschaden zu und friert sie bis zu 8 Sek. lang fest. Erlittener Schaden kann den Effekt unterbrechen." }
entries[145533] = { ["name"] = "Eisblock", ["text"] = "Sofort 5 min Abklingzeit\nIhr werdet in einen Eisblock eingehüllt, der Euch 5 Sek. lang vor allen körperlichen Angriffen und Zaubern schützt. Allerdings könnt Ihr während dieser Zeit weder angreifen noch Euch bewegen und auch keine Zauber wirken." }
entries[145534] = { ["name"] = "Zeitkrümmung", ["text"] = "100 Meter Reichweite\nSofort 5 min Abklingzeit\nKrümmt den Lauf der Zeit, wodurch das Nahkampf-, Distanzangriffs- und Zaubertempo aller Gruppen- und Schlachtzugsmitglieder um 30% erhöht wird. Hält 40 Sek. lang an." }
entries[145535] = { ["name"] = "Blinzeln", ["text"] = "Sofort 15 sek. Abklingzeit\nTeleportiert den Zaubernden 20 Meter nach vorn, es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungs- und Bewegungsunfähigkeitseffekten." }
