entries[145537] = { ["name"] = "Steinabbild", ["text"] = "Sofort\nEntzieht Spielercharakteren einen Teil ihrer Lebensessenz, stößt sie zurück und fügt ihnen 1553 Schattenschaden zu. Aus der Lebensessenz wird eine Steinstatue erstellt.\n\nDiese Statue schlägt regelmäßig auf den Boden. Dadurch fügt sie allen Zielen in einem kegelförmigen Bereich vor ihr 4479 körperlichen Schaden zu und betäubt sie lang. Diese Statue bleibt bestehen, bis sie getötet wird." }
entries[145547] = { ["name"] = "Elektrifizierter Boden", ["text"] = "Wirken in 2.5 sek.\nElektrifiziert den Boden und fügt allen Gegnern im Umkreis von 6 Metern um den Zaubernden 4739 Naturschaden zu." }
